import {createLabelLayout} from './world-labels.js';
import {sharedSeatPose} from './ride-seats.js';
import {interiorAt} from './interior-layout.js';
import {decodeActivity} from './activity-state.js';
import {createActivityReactions} from './activity-reactions.js';
import * as T from './vendor/three.module.js';
import {createCompanion} from './companion.js';
import {moveOnGround} from './movement.js';
import {clearSegment,findPath} from './navigation.js';
import {surfaceHeight} from './world-layout.js';
import {projectedCharacterHeight} from './render-budget.js';
export function createVisitors(scene,{rideChair=null}={}){
 const remoteChairs=new Map();
 function updateChairs(){const active=new Set();for(const reservation of window.labRideSeats||[]){if(!['lift','upperlift'].includes(reservation.kind))continue;const key=reservation.kind+':'+reservation.cabin,own=window.labRideReservation;if(own&&own.kind===reservation.kind&&own.cabin===reservation.cabin)continue;active.add(key);let chair=remoteChairs.get(key);if(!chair&&rideChair){chair=rideChair.clone(true);chair.name='shared-lift-chair-'+key;scene.add(chair);remoteChairs.set(key,chair);}if(chair){const p=sharedSeatPose(reservation,Date.now()+(window.labServerOffset||0)),offset=reservation.seat===1?.95:-.95;chair.position.set(p.x-Math.cos(p.yaw)*offset,p.y-.82,p.z+Math.sin(p.yaw)*offset);chair.rotation.set(0,p.yaw,0);chair.visible=!window.labInterior&&!p.finished;}}for(const [key,chair]of remoteChairs)if(!active.has(key)){chair.removeFromParent();remoteChairs.delete(key);}}
 const peers=new Map(),container=document.querySelector('#visitor-labels'),screen=new T.Vector3(),frustum=new T.Frustum(),projection=new T.Matrix4(),bounds=new T.Sphere(new T.Vector3(),3.5),destination=new T.Vector3();
 function remove(id,p){scene.remove(p.pet.group);p.reactions.dispose?.();p.bounds.dispose();p.label.remove();p.pet.dispose();peers.delete(id);}
 const onVisitors=e=>{const ids=new Set(e.detail.map(p=>p.id));for(const [id,p]of peers)if(!ids.has(id))remove(id,p);for(const state of e.detail){let peer=peers.get(state.id);if(!peer){const pet=createCompanion({detail:'remote'}),label=document.createElement('span');label.className='visitor-label';const name=document.createElement('b'),bubble=document.createElement('div');name.textContent=state.name;bubble.className='speech-bubble';label.append(name,bubble);container.append(label);pet.group.position.set(state.x,state.y??.95,state.z);scene.add(pet.group);peer={pet,label,state,route:[],fx:{id:state.id},bounds:createLabelLayout(label),animationElapsed:0,reactions:createActivityReactions(scene)};peers.set(state.id,peer);}const current=peer.pet.group.position;peer.route=peer.onScreen!==false&&!state.mode&&Math.hypot(current.x-state.x,current.z-state.z)>.05&&Math.hypot(current.x-state.x,current.z-state.z)<12&&!clearSegment(current,state)?findPath(current,state):[];peer.state=state;if(peer.label.querySelector('b').textContent!==state.name)peer.label.querySelector('b').textContent=state.name;const bubble=peer.label.querySelector('.speech-bubble');if(bubble.textContent!==(state.chat||''))bubble.textContent=state.chat||'';bubble.hidden=!state.chat||Date.now()-state.chatAt>6500;const appearance=[state.color,state.accessory,state.fluff,state.roundness].join('|');if(peer.appearance!==appearance){peer.appearance=appearance;peer.pet.customize({fur:state.color,accessory:state.accessory,fluff:state.fluff??100,roundness:state.roundness??50});}peer.pet.equip(['ski','lift','summit'].includes(state.mode)?(peer.pet.gear==='board'?'board':'ski'):state.mode==='sled'?'sled':state.mode==='skate'?'skates':['bath','sauna','lie','tea','dining','carousel','ferris'].includes(state.mode)?'none':peer.pet.gear);}};window.addEventListener('lab:visitors',onVisitors);
 const ownLabel=document.querySelector('#self-label'),ownLayout=ownLabel?createLabelLayout(ownLabel):null;

 return{dispose(){window.removeEventListener('lab:visitors',onVisitors);for(const [id,p]of peers)remove(id,p);for(const chair of remoteChairs.values())chair.removeFromParent();remoteChairs.clear();ownLayout?.dispose();},effectStates(){return [...peers.values()].filter(p=>p.pet.group.visible).map(p=>p.fx);},update(dt,time,camera,ownBounds=null){updateChairs();frustum.setFromProjectionMatrix(projection.multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse));const occupied=ownBounds?[ownBounds]:[];for(const p of peers.values()){const assigned=window.labRideSeats?.find(s=>s.id===p.state.id),synced=assigned?sharedSeatPose(assigned,Date.now()+(window.labServerOffset||0)):null,s=synced?{...p.state,...synced}:p.state,g=p.pet.group;bounds.center.set(s.x,(s.y??.95)+.6,s.z);const visible=((s.region&&s.region!=='outdoors'?s.region:interiorAt(s.x,s.z)?.id)||null)===(window.labInterior||null)&&frustum.intersectsSphere(bounds)&&!window.isVisitorBlocked?.(s.id);g.visible=visible;if(!visible){g.position.set(s.x,s.y??.95,s.z);p.label.hidden=true;p.route=[];if(p.onScreen!==false)p.reactions.suspend();p.onScreen=false;continue;}p.onScreen=true;const pixels=projectedCharacterHeight(camera,g.position,innerHeight);p.pet.setViewDetail(pixels);const oldX=g.position.x,oldZ=g.position.z,d=Math.hypot(oldX-s.x,oldZ-s.z),blend=1-Math.exp(-dt*5);
  if(d>12){g.position.set(s.x,s.y??.95,s.z);p.route=[];}
  else if(!s.mode){while(p.route.length&&Math.hypot(g.position.x-p.route[0].x,g.position.z-p.route[0].z)<.12)p.route.shift();const target=p.route[0]||s,step=moveOnGround(g.position,{x:(target.x-g.position.x)*blend/Math.max(dt,.001),z:(target.z-g.position.z)*blend/Math.max(dt,.001)},dt);g.position.x=step.x;g.position.z=step.z;g.position.y=Math.max(surfaceHeight(step.x,step.z)+.86,g.position.y+((s.y??.95)-g.position.y)*blend);}
  else if(synced)g.position.set(s.x,s.y,s.z);else g.position.lerp(destination.set(s.x,s.y??.95,s.z),blend);
  Object.assign(p.fx,{x:g.position.x,y:g.position.y,z:g.position.z,yaw:g.rotation.y,mode:s.mode,accessory:s.accessory,emote:s.gesture,speed:d>12?0:Math.min(40,Math.hypot(g.position.x-oldX,g.position.z-oldZ)/Math.max(dt,.001))});
  const turn=Math.atan2(Math.sin(s.yaw-g.rotation.y),Math.cos(s.yaw-g.rotation.y));g.rotation.y+=turn*blend;p.animationElapsed+=dt;if(p.animationElapsed>=(pixels<30?1/15:pixels<65?1/30:0)){p.pet.pose({room:(s.region&&s.region!=='outdoors'?s.region:interiorAt(s.x,s.z)?.id),mode:s.mode,...decodeActivity(s.gesture||''),walking:d>.15&&(!s.mode||s.mode==='summit'),phase:time*7,time});p.reactions.update({...decodeActivity(s.gesture||''),mode:s.mode,x:g.position.x,y:g.position.y,z:g.position.z,yaw:g.rotation.y,time,dt:p.animationElapsed,still:document.body.classList.contains('still')});p.animationElapsed=0;}screen.copy(g.position);screen.y+=p.pet.nameHeight;screen.project(camera);p.label.hidden=Math.abs(screen.z)>1||Math.abs(screen.x)>1.12||Math.abs(screen.y)>1.12;const bubble=p.label.querySelector('.speech-bubble'),remaining=6500-(Date.now()-s.chatAt);bubble.hidden=!s.chat||remaining<=0;bubble.style.opacity=String(Math.max(0,Math.min(1,remaining/700)));
  const x=(screen.x*.5+.5)*innerWidth;let y=(-screen.y*.5+.5)*innerHeight-6;p.label.style.transform=`translate(${x}px,${y}px) translate(-50%,-100%)`;if(!p.label.hidden){let rect=p.bounds.bounds(x,y);for(const avoid of occupied){if(rect.right>avoid.left-5&&rect.left<avoid.right+5&&rect.bottom>avoid.top-5&&rect.top<avoid.bottom+5){const dy=rect.bottom-avoid.top+7;y-=dy;rect.top-=dy;rect.bottom-=dy;}}p.label.style.transform=`translate(${x}px,${y}px) translate(-50%,-100%)`;occupied.push(rect);}
 }}};
}
